// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import "../interfaces/IFactory.sol";
import "../interfaces/IPool.sol";
import "hardhat/console.sol";

/// @title Math library for computing sqrt prices from ticks and vice versa
/// @notice Computes sqrt price for ticks of size 1.0001, i.e. sqrt(1.0001^tick) as fixed point Q64.96 numbers. Supports
/// prices between 2**-128 and 2**128
library TickMath {
    /// @dev The minimum tick that may be passed to #getSqrtRatioAtTick computed from log base 1.0001 of 2**-128
    int24 internal constant MIN_TICK = -887272;
    /// @dev The maximum tick that may be passed to #getSqrtRatioAtTick computed from log base 1.0001 of 2**128
    int24 internal constant MAX_TICK = -MIN_TICK;

    /// @dev The minimum value that can be returned from #getSqrtRatioAtTick. Equivalent to getSqrtRatioAtTick(MIN_TICK)
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    /// @dev The maximum value that can be returned from #getSqrtRatioAtTick. Equivalent to getSqrtRatioAtTick(MAX_TICK)
    uint160 internal constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;

    /// @notice Calculates sqrt(1.0001^tick) * 2^96
    /// @dev Throws if |tick| > max tick
    /// @param tick The input tick for the above formula
    /// @return sqrtPriceX96 A Fixed point Q64.96 number representing the sqrt of the ratio of the two assets (token1/token0)
    /// at the given tick
    function getSqrtRatioAtTick(int24 tick) public pure returns (uint160 sqrtPriceX96) {
        uint256 absTick = tick < 0 ? uint256(uint24(-tick)) : uint256(uint24(tick));
        // *수정했음
        require(absTick <= uint256(uint24(MAX_TICK)), 'T');

        uint256 ratio = absTick & 0x1 != 0 ? 0xfffcb933bd6fad37aa2d162d1a594001 : 0x100000000000000000000000000000000;
        if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
        if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
        if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
        if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
        if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
        if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
        if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
        if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
        if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
        if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
        if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
        if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
        if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
        if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
        if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
        if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
        if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
        if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
        if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;

        if (tick > 0) ratio = type(uint256).max / ratio;

        // this divides by 1<<32 rounding up to go from a Q128.128 to a Q128.96.
        // we then downcast because we know the result always fits within 160 bits due to our tick input constraint
        // we round up in the division so getTickAtSqrtRatio of the output price is always consistent
        sqrtPriceX96 = uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
    }

    /// @notice Calculates the greatest tick value such that getRatioAtTick(tick) <= ratio
    /// @dev Throws in case sqrtPriceX96 < MIN_SQRT_RATIO, as MIN_SQRT_RATIO is the lowest value getRatioAtTick may
    /// ever return.
    /// @param sqrtPriceX96 The sqrt ratio for which to compute the tick as a Q64.96
    /// @return tick The greatest tick for which the ratio is less than or equal to the input ratio
    function getTickAtSqrtRatio(uint160 sqrtPriceX96) external pure returns (int24 tick) {
        // second inequality must be < because the price can never reach the price at the max tick
        require(sqrtPriceX96 >= MIN_SQRT_RATIO, 'R');
        require( sqrtPriceX96 < MAX_SQRT_RATIO, 'L');
        uint256 ratio = uint256(sqrtPriceX96) << 32;

        uint256 r = ratio;
        uint256 msb = 0;

        assembly {
            let f := shl(7, gt(r, 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := shl(6, gt(r, 0xFFFFFFFFFFFFFFFF))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := shl(5, gt(r, 0xFFFFFFFF))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := shl(4, gt(r, 0xFFFF))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := shl(3, gt(r, 0xFF))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := shl(2, gt(r, 0xF))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := shl(1, gt(r, 0x3))
            msb := or(msb, f)
            r := shr(f, r)
        }
        assembly {
            let f := gt(r, 0x1)
            msb := or(msb, f)
        }

        if (msb >= 128) r = ratio >> (msb - 127);
        else r = ratio << (127 - msb);

        int256 log_2 = (int256(msb) - 128) << 64;

        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(63, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(62, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(61, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(60, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(59, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(58, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(57, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(56, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(55, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(54, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(53, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(52, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(51, f))
            r := shr(f, r)
        }
        assembly {
            r := shr(127, mul(r, r))
            let f := shr(128, r)
            log_2 := or(log_2, shl(50, f))
        }

        int256 log_sqrt10001 = log_2 * 255738958999603826347141; // 128.128 number

        int24 tickLow = int24((log_sqrt10001 - 3402992956809132418596140100660247210) >> 128);
        int24 tickHi = int24((log_sqrt10001 + 291339464771989622907027621153398088495) >> 128);

        tick = tickLow == tickHi ? tickLow : getSqrtRatioAtTick(tickHi) <= sqrtPriceX96 ? tickHi : tickLow;
    }
}

contracts/NonfungiblePositionManager.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

// Uncomment this line to use console.log
import "hardhat/console.sol";

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./interfaces/IMintCallBack.sol";
import "./lib/PoolHelper.sol";
import "./lib/TickMath.sol";
import "./lib/SqrtPriceMath.sol";

contract NonfungiblePositionManager is ERC721, IMintCallBack{
    event AddLiquidity(
        uint256 tokenId,
        uint256 liquidity,
        uint256 amount0,
        uint256 amount1
    );
    
    event RemoveLiquidity(
        uint256 tokenId,
        uint256 liquidity,
        uint256 amount0,
        uint256 amount1
    );

    event Collect(
        uint256 tokenId,
        address to,
        uint256 indexed amount0Collect,
        uint256 indexed amount1Collect
    );

    struct Positions {
        // the nonce for permits
        uint96 nonce;
        // the address that is approved for spending this token
        address operator;
        // the ID of the pool with which this token is connected
        uint80 poolId;
        // the tick range of the position
        int24 tickLower;
        int24 tickUpper;
        // the liquidity of the position
        uint128 liquidity;
        // the fee growth of the aggregate position as of the last action on the individual position
       uint256 feeGrowthInside0LastX128;
       uint256 feeGrowthInside1LastX128;
        // how many uncollected tokens are owed to the position, as of the last computation
        uint128 tokensOwed0;
        uint128 tokensOwed1;
    }

    struct PoolInfo {
        address token0;
        address token1;
        uint24 fee;
    }

    struct MintCallbackData {
        PoolInfo poolInfo;
        address to;
    }

    struct AddLiquidityParams {
        address token0;
        address token1;
        int24 tickLower;
        int24 tickUpper;
        uint amount0Desired;
        uint amount1Desired;
        uint amount0Min;
        uint amount1Min;
        uint24 fee;
        address to;
    }

    struct RemoveLiquidityParams {
        uint128 liquidity;
        uint176 tokenId;
        uint80 poolId;
        uint amount0Min;
        uint amount1Min;
    }


    // collect의 max는 왜 필요함?
    struct CollectParmas {
        uint176 tokenId;
        address to;
    }

    modifier isAuthorizedForToken(uint256 tokenId) {
        require(msg.sender == ownerOf(tokenId), 'Not approved');
        _;
    }

    // poolAddress -> poolId
    mapping(address => uint80) private _poolIds;
    
    // token Id -> position info
    mapping(uint256 => Positions) private _positions;
    
    // Position.PoolId -> PoolInfo
    mapping(uint80 => PoolInfo) private _poolIdToPoolInfo;
    uint176 private _nextId = 1;
    uint80 private _nextPoolId = 1;

    //   address private immutable _tokenDescriptor;

    address public factory;

    uint256 constant Q128 = 0x100000000000000000000000000000000;
    

    constructor(address _factory) ERC721('Uniswap Positions NFT', 'UNI-POS-NFT'){
        factory = _factory;
    }


   function mintCallBack( uint256 amount0, uint256 amount1, bytes calldata data) external override{
        MintCallbackData memory decoded = abi.decode(data, (MintCallbackData));

        // callback validation
        require(msg.sender == PoolHelper.getPool(factory, decoded.poolInfo.token0, decoded.poolInfo.token1), 'Invalid sender');

        if (amount0 > 0) IERC20(decoded.poolInfo.token0).transferFrom(decoded.to, msg.sender, amount0);
        if (amount1 > 0) IERC20(decoded.poolInfo.token1).transferFrom(decoded.to, msg.sender, amount1);
    }

    /// @dev Caches a pool info
    function cachePoolInfo(address pool, PoolInfo memory poolInfo) private returns (uint80 poolId) {
        poolId = _poolIds[pool];
        if (poolId == 0) {
            _poolIds[pool] = (poolId = _nextPoolId++);
            _poolIdToPoolInfo[poolId] = poolInfo;
        }
    }
    
    function getPosition(uint256 tokenId) external view
        returns (
            uint96 nonce,
            address operator,
            address token0,
            address token1,
            uint24 fee,
            int24 tickLower,
            int24 tickUpper,
            uint128 liquidity,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        )
    {
        Positions memory positions = _positions[tokenId];
        require(positions.poolId != 0, 'Invalid token ID');
        PoolInfo memory poolInfo = _poolIdToPoolInfo[positions.poolId];
        return (
            positions.nonce,
            positions.operator,
            poolInfo.token0,
            poolInfo.token1,
            poolInfo.fee,
            positions.tickLower,
            positions.tickUpper,
            positions.liquidity,
            positions.feeGrowthInside0LastX128,
            positions.feeGrowthInside1LastX128,
            positions.tokensOwed0,
            positions.tokensOwed1
        );
    }


    // 남은 금액은 어차피 approve만 해놔서 잔돈 안 돌려줘도 됨.
    function addLiquidity(AddLiquidityParams calldata params) 
        public 
        returns
        (uint256 amount0, uint256 amount1, uint128 liquidity, uint256 tokenId)
    {
        
        PoolInfo memory poolInfo = PoolInfo({token0: params.token0, token1: params.token1, fee: params.fee});

        IPool pool = IPool(PoolHelper.getPool(factory, params.token0, params.token1));        

        {
            uint160 sqrtPriceX96 = pool.getCurrentSqrtPriceX96();
            uint160 sqrtRatioAX96 = TickMath.getSqrtRatioAtTick(params.tickLower);
            uint160 sqrtRatioBX96 = TickMath.getSqrtRatioAtTick(params.tickUpper);

            // tick이 음수인 경우 swap
            if (sqrtRatioAX96 > sqrtRatioBX96) (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);

            if (sqrtPriceX96 <= sqrtRatioAX96) {
                liquidity = SqrtPriceMath.getLiquidityForAmount0(sqrtRatioAX96, sqrtRatioBX96, params.amount0Desired);
            } 
            else if (sqrtPriceX96 < sqrtRatioBX96) {
                uint128 liquidity0 = SqrtPriceMath.getLiquidityForAmount0(sqrtPriceX96, sqrtRatioBX96, params.amount0Desired);
                uint128 liquidity1 = SqrtPriceMath.getLiquidityForAmount1(sqrtRatioAX96, sqrtPriceX96, params.amount1Desired);

                liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
            } else {
                liquidity = SqrtPriceMath.getLiquidityForAmount1(sqrtRatioAX96, sqrtRatioBX96, params.amount1Desired);
            }
        }
        (amount0, amount1) = pool.mint(params.tickLower, params.tickUpper, liquidity, abi.encode(MintCallbackData({poolInfo: poolInfo, to : msg.sender})));

        require(amount0 >= params.amount0Min && amount1 >= params.amount1Min, 'Price slippage check');

        _mint(params.to, (tokenId = _nextId++));

        (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , ) = pool.getPositions(params.tickLower, params.tickUpper);

        uint80 poolId = cachePoolInfo( address(pool), PoolInfo({token0: params.token0, token1: params.token1, fee: params.fee}));

         _positions[tokenId] = Positions({
            nonce: 0,
            operator: address(0),
            poolId: poolId,
            tickLower: params.tickLower,
            tickUpper: params.tickUpper,
            liquidity: liquidity,
            feeGrowthInside0LastX128: feeGrowthInside0LastX128,
            feeGrowthInside1LastX128: feeGrowthInside1LastX128,
            tokensOwed0: 0,
            tokensOwed1: 0
        });

        // event 발생
        emit AddLiquidity(tokenId, liquidity, amount0, amount1);
    }


    // 기존의 NFT에 Liquidity 추가하는 함수 = increaseLiquidity() 구현해야함.........

    // 유동성을 제거하지만 NFT의 tokenOwed는 남아 있음
    function removeLiquidity(RemoveLiquidityParams calldata params) 
        external
        isAuthorizedForToken(params.tokenId) 
        returns (uint amount0, uint amount1)
    {
        Positions storage position = _positions[params.tokenId]; 
        uint128 positionLiquidity = position.liquidity;
        require(positionLiquidity >= params.liquidity);
        

        PoolInfo memory poolInfo = _poolIdToPoolInfo[params.poolId];
        IPool pool = IPool(PoolHelper.getPool(factory, poolInfo.token0, poolInfo.token1));        

        (amount0, amount1) = pool.burn(position.tickLower, position.tickUpper, params.liquidity);
        require(amount0 >= params.amount0Min && amount1 >= params.amount1Min, 'Price slippage check');
        (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , ) = pool.getPositions(position.tickLower, position.tickUpper);

        position.tokensOwed0 +=
            uint128(amount0) +
            uint128(
                    Math.mulDiv(
                    feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128,
                    positionLiquidity,
                    Q128
                )
            );
        position.tokensOwed1 +=
            uint128(amount1) +
            uint128(
                    Math.mulDiv(
                    feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128,
                    positionLiquidity,
                    Q128
                )
            );
        position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
        position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;

        position.liquidity = positionLiquidity - params.liquidity;

        emit RemoveLiquidity(params.tokenId, params.liquidity, amount0, amount1);
    }


    function collect(CollectParmas calldata params) 
        external 
        payable 
        isAuthorizedForToken(params.tokenId) 
        returns(uint256 amount0, uint256 amount1)
    {
        Positions storage position = _positions[params.tokenId];

        PoolInfo memory poolInfo = _poolIdToPoolInfo[position.poolId];

        IPool pool = IPool(PoolHelper.getPool(factory, poolInfo.token0, poolInfo.token1));    

        (uint128 tokensOwed0, uint128 tokensOwed1) = (position.tokensOwed0, position.tokensOwed1);

        if(position.liquidity > 0){
            // feeInside update
            pool.burn(position.tickLower, position.tickUpper, 0);
            (, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, , ) = pool.getPositions(position.tickLower, position.tickUpper);
            
            tokensOwed0 += uint128(
                Math.mulDiv(
                    feeGrowthInside0LastX128 - position.feeGrowthInside0LastX128,
                    position.liquidity,
                    Q128
                )
            );
            tokensOwed1 += uint128(
                Math.mulDiv(
                    feeGrowthInside1LastX128 - position.feeGrowthInside1LastX128,
                    position.liquidity,
                    Q128
                )
            );

            position.feeGrowthInside0LastX128 = feeGrowthInside0LastX128;
            position.feeGrowthInside1LastX128 = feeGrowthInside1LastX128;
        }

        (amount0, amount1) = pool.collect(params.to, position.tickLower, position.tickUpper, tokensOwed0, tokensOwed1);

        // *수정 amountMax 추가 시 변경
        position.tokensOwed0 = 0;
        position.tokensOwed1 = 0;

        emit Collect(params.tokenId, params.to, tokensOwed0, tokensOwed1);
    }
}

contracts/Pool.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

// Uncomment this line to use console.log
import "hardhat/console.sol";

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./lib/Tick.sol";
import "./lib/Position.sol";
import "./lib/SqrtPriceMath.sol";
import "./lib/TickMath.sol";
import "./lib/SwapMath.sol";
import './lib/TickBitmap.sol';
import './interfaces/IMintCallBack.sol';
import "./interfaces/ISwapCallBack.sol";
import "./interfaces/IPool.sol";

contract Pool is IPool {
    using Tick for mapping(int24 => Tick.Info);
    using Position for mapping(int24 => mapping(int24 => Position.Info));
    using Position for Position.Info;
    using TickBitmap for mapping(int16 => uint256);

    address public immutable token0;
    address public immutable token1;
    address public immutable owner;
    int24 public immutable tickSpacing = 1;
    uint256 constant Q128 = 0x100000000000000000000000000000000;

     struct Slot0 {
        // the current price
        uint160 sqrtPriceX96;
        // the current tick
        int24 tick;
        // the most-recently updated index of the observations array
        uint16 observationIndex;
        // the current maximum number of observations that are being stored
        uint16 observationCardinality;
        // the next maximum number of observations to store, triggered in observations.write
        uint16 observationCardinalityNext;
        bool unlocked;
    }

    uint24 public fee;
    uint256 public feeGrowthGlobal0X128;
    uint256 public feeGrowthGlobal1X128;
    uint128 public liquidity;
    Slot0 public slot0;
    // [lowerTick][upperTick] => position.info
    mapping(int24 => mapping(int24 => Position.Info)) public positions;
    mapping(int24 => Tick.Info) public ticks;
    
    mapping(int16 => uint256) public tickBitmap;

    constructor(address _token0, address _token1, uint160 sqrtPriceX96) {
        token0 = _token0;
        token1 = _token1;
        owner = msg.sender;
        fee = 3000;
        slot0 = Slot0({
         sqrtPriceX96 : sqrtPriceX96,
         tick : TickMath.getTickAtSqrtRatio(sqrtPriceX96),
         observationIndex : 0,
         observationCardinality : 0,
         observationCardinalityNext : 0,
         unlocked: true
        });
    }

    function _updatePosition(int24 tickLower, int24 tickUpper, int128 liquidityDelta, int24 tick) private returns(Position.Info storage position){
        
        position = positions[tickLower][tickUpper];

        uint256 _feeGrowthGlobal0X128 = feeGrowthGlobal0X128;
        uint256 _feeGrowthGlobal1X128 = feeGrowthGlobal1X128; 

        bool flippedLower = ticks.update(
                tickLower,
                tick,
                liquidityDelta,
                _feeGrowthGlobal0X128,
                _feeGrowthGlobal1X128,
                false
            );

        bool flippedUpper = ticks.update(
                tickUpper,
                tick,
                liquidityDelta,
                _feeGrowthGlobal0X128,
                _feeGrowthGlobal1X128,
                true
            );

        if (flippedLower)  
            tickBitmap.flipTick(tickLower, tickSpacing);
        
        if (flippedUpper)  
            tickBitmap.flipTick(tickUpper, tickSpacing);
        
        // Position 안의 FeeGrowth 구하기 / 유동성 공급/제거로는 Fee는 변화가 없지만 최신화만
        (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128) =
            ticks.getFeeGrowthInside(tickLower, tickUpper, tick, _feeGrowthGlobal0X128, _feeGrowthGlobal1X128);

        // Position Update
        position.update(liquidityDelta ,feeGrowthInside0X128, feeGrowthInside1X128);


        // 근데 유동성을 0이하로 빼면 어카냐?
        if(liquidityDelta < 0){
            if(flippedLower)
                ticks.clear(tickLower);
            if(flippedUpper)
                ticks.clear(tickUpper);
        }
    }

    function _modifyPosition(int24 tickLower, int24 tickUpper, int128 liquidityDelta) private returns(Position.Info storage position, int256 amount0, int256 amount1){
        require(tickLower < tickUpper, 'TLU');
        Slot0 memory _slot0 = slot0; 

        position = _updatePosition(tickLower, tickUpper, liquidityDelta, _slot0.tick);

        uint128 liquidityBefore = liquidity;

        if(liquidityDelta != 0){
            if(_slot0.tick < tickLower){
                amount0 = SqrtPriceMath.getAmount0Delta(
                    TickMath.getSqrtRatioAtTick(tickLower),
                    TickMath.getSqrtRatioAtTick(tickUpper),
                    liquidityDelta);
            }
            else if(_slot0.tick < tickUpper){
                amount0 = SqrtPriceMath.getAmount0Delta(
                    _slot0.sqrtPriceX96,
                    TickMath.getSqrtRatioAtTick(tickUpper),
                    liquidityDelta);
                
                amount1 = SqrtPriceMath.getAmount1Delta(
                    TickMath.getSqrtRatioAtTick(tickLower),
                    _slot0.sqrtPriceX96,
                    liquidityDelta);

                liquidity = liquidityDelta > 0 ? liquidityBefore + uint128(liquidityDelta) : liquidityBefore - uint128(-liquidityDelta);
            }
            else {
                amount1 = SqrtPriceMath.getAmount1Delta(
                    TickMath.getSqrtRatioAtTick(tickLower),
                    TickMath.getSqrtRatioAtTick(tickUpper),
                    liquidityDelta);
            }
        }
    }



    function mint(int24 tickLower, int24 tickUpper, uint128 amount, bytes calldata data) external override returns (uint256 amount0, uint256 amount1){

        // *수정 modify Position -> Liquidity update
         (, int256 amount0Int, int256 amount1Int) = _modifyPosition(tickLower, tickUpper, int128(amount));
        amount0 = uint256(amount0Int);
        amount1 = uint256(amount1Int);
        uint256 balance0Before;
        uint256 balance1Before;

        if (amount0 > 0) balance0Before = IERC20(token0).balanceOf(address(this));
        if (amount1 > 0) balance1Before = IERC20(token1).balanceOf(address(this));

        IMintCallBack(msg.sender).mintCallBack(amount0, amount1, data);

        if (amount0 > 0) require(balance0Before + amount0 <= IERC20(token0).balanceOf(address(this)), 'M0');
        if (amount1 > 0) require(balance1Before + amount1 <= IERC20(token1).balanceOf(address(this)), 'M1');
        // event 발생
    }

    function burn(int24 tickLower, int24 tickUpper, uint128 amount) external override returns (uint256 amount0, uint256 amount1){
        (Position.Info storage position, int256 amount0Int, int256 amount1Int) = _modifyPosition(tickLower, tickUpper, -int128(amount));
        amount0 = uint256(-amount0Int);
        amount1 = uint256(-amount1Int);

        if(amount0 > 0 || amount1 > 0){
            position.tokensOwed0 += uint128(amount0);
            position.tokensOwed1 += uint128(amount1);
        }
    }

    function collect(address to, int24 tickLower, int24 tickUpper, uint128 amount0Requested,uint128 amount1Requested) external override returns (uint128 amount0, uint128 amount1){
        Position.Info storage position = positions[tickLower][tickUpper];

        // max
        amount0 = amount0Requested > position.tokensOwed0 ? amount0Requested : position.tokensOwed0;
        amount1 = amount1Requested > position.tokensOwed1 ? amount1Requested : position.tokensOwed1;
        
        if(amount0 > 0){
            position.tokensOwed0 -= amount0;
            IERC20(token0).transfer(to, amount0);
        }

        if(amount1 > 0){
            position.tokensOwed1 -= amount1;
            IERC20(token1).transfer(to, amount1);
        }

        // event 발생!!        
    }


    struct SwapCache {
        // liquidity at the beginning of the swap
        uint128 liquidityStart;
        // the current value of the tick accumulator, computed only if we cross an initialized tick
        int56 tickCumulative;
    }

     // the top level state of the swap, the results of which are recorded in storage at the end
    struct SwapState {
        // the amount remaining to be swapped in/out of the input/output asset
        int256 amountSpecifiedRemaining;
        // the amount already swapped out/in of the output/input asset
        int256 amountCalculated;
        // current sqrt(price)
        uint160 sqrtPriceX96;
        // the tick associated with the current price
        int24 tick;
        // the global fee growth of the input token
        uint256 feeGrowthGlobalX128;
        // the current liquidity in range
        uint128 liquidity;
    }

    struct StepComputations {
        // the price at the beginning of the step
        uint160 sqrtPriceStartX96;
        // the next tick to swap to from the current tick in the swap direction
        int24 tickNext;
        // whether tickNext is initialized or not
        bool initialized;
        // sqrt(price) for the next tick (1/0)
        uint160 sqrtPriceNextX96;
        // how much is being swapped in in this step
        uint256 amountIn;
        // how much is being swapped out
        uint256 amountOut;
        // how much fee is being paid in
        uint256 feeAmount;
    }


    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external override  returns (int256 amount0, int256 amount1) {
     
        Slot0 memory slot0Start = slot0;

        require(slot0Start.unlocked);

        slot0Start.unlocked = false;

        bool exactIn = amountSpecified > 0;

        SwapCache memory cache = SwapCache({
            liquidityStart: liquidity,
            tickCumulative: 0
        });

        SwapState memory state = SwapState({
            amountSpecifiedRemaining : amountSpecified,
            amountCalculated : 0,
            sqrtPriceX96 : slot0Start.sqrtPriceX96,
            tick : slot0Start.tick,
            feeGrowthGlobalX128 : zeroForOne ? feeGrowthGlobal0X128 : feeGrowthGlobal1X128,
            liquidity : cache.liquidityStart
        });


        while(state.amountSpecifiedRemaining != 0 && state.sqrtPriceX96 != sqrtPriceLimitX96){
            StepComputations memory step;

            step.sqrtPriceStartX96 = state.sqrtPriceX96;

            (step.tickNext, step.initialized) = tickBitmap.nextInitializedTickWithinOneWord(
                state.tick,
                tickSpacing,
                zeroForOne
            );

            // ensure that we do not overshoot the min/max tick, as the tick bitmap is not aware of these bounds
            if (step.tickNext < TickMath.MIN_TICK) {
                step.tickNext = TickMath.MIN_TICK;
            } else if (step.tickNext > TickMath.MAX_TICK) {
                step.tickNext = TickMath.MAX_TICK;
            }

            step.sqrtPriceNextX96 = TickMath.getSqrtRatioAtTick(step.tickNext);

            (state.sqrtPriceX96, step.amountIn, step.amountOut, step.feeAmount) = SwapMath.computeSwapStep(
                state.sqrtPriceX96,
                (zeroForOne ?  step.sqrtPriceNextX96 < sqrtPriceLimitX96 : step.sqrtPriceNextX96 > sqrtPriceLimitX96)
                    ? sqrtPriceLimitX96 
                    : step.sqrtPriceNextX96, 
                 state.liquidity,
                 state.amountSpecifiedRemaining,
                 fee    
            );

            if(exactIn){
                // + -> 0  : 남은 amountIn의 양
                state.amountSpecifiedRemaining -= int256(step.amountIn + step.feeAmount);
                // 0 -> - :  amountOut의 합
                state.amountCalculated -= int256(step.amountOut);
            }
            else{
                // - -> 0  : 남은 amountOut의 양
                state.amountSpecifiedRemaining += int256(step.amountOut);
                // 0 -> +  : amountIn의 합
                state.amountCalculated += int256(step.amountIn + step.feeAmount);
            }

            
            if(state.liquidity > 0) {
                state.feeGrowthGlobalX128 += Math.mulDiv(step.feeAmount, Q128, state.liquidity);
            }

            // Shift Tick if target price riched the next price
            if(state.sqrtPriceX96 == step.sqrtPriceNextX96){
                // bitmap init
                if(step.initialized){
                    int128 liquidityNet = ticks.cross(
                        step.tickNext,
                        zeroForOne ? state.feeGrowthGlobalX128 : feeGrowthGlobal0X128,
                        zeroForOne ? feeGrowthGlobal1X128 : state.feeGrowthGlobalX128
                    );

                    state.liquidity = zeroForOne ? state.liquidity - uint128(-liquidityNet) : state.liquidity + uint128(liquidityNet);
                }

                state.tick = zeroForOne ? state.tick - 1: state.tick;
            }
            else{
                // cross tick이 끝났을 때 || 안 변했을 때 tick update
                state.tick = TickMath.getTickAtSqrtRatio(state.sqrtPriceX96);
            }

        }

        // slot0에 update
        if(state.tick != slot0Start.tick){
            slot0.sqrtPriceX96 = state.sqrtPriceX96;
            slot0.tick = state.tick;
        }
        else{
            slot0.sqrtPriceX96 = state.sqrtPriceX96;
        }

        // liquidity Update
        if(cache.liquidityStart != state.liquidity) liquidity = state.liquidity;

        
        // Global Fee update
        if(zeroForOne){
            feeGrowthGlobal0X128 = state.feeGrowthGlobalX128;
        }
        else{
            feeGrowthGlobal1X128 = state.feeGrowthGlobalX128;
        }

        // zeroForOne  1. A'-> B / 2. A -> B' / 2. B'->A / 1. B -> A'
        (amount0, amount1) = zeroForOne == exactIn
            ? (amountSpecified - state.amountSpecifiedRemaining, state.amountCalculated)
            : (state.amountCalculated, amountSpecified - state.amountSpecifiedRemaining);


        // transfer
        if(zeroForOne){
            if(amount1 < 0) IERC20(token1).transfer(recipient, uint256(-amount1));

            uint256 balance0Before = IERC20(token0).balanceOf(address(this));
            ISwapCallBack(msg.sender).swapCallBack(amount0, amount1, data);
            require(balance0Before + uint256(amount0) <= IERC20(token0).balanceOf(address(this)));
        }
        else{
            if(amount0 < 0) IERC20(token0).transfer(recipient, uint256(-amount0));

            uint256 balance1Before = IERC20(token1).balanceOf(address(this));
            ISwapCallBack(msg.sender).swapCallBack(amount0, amount1, data);
            require(balance1Before + uint256(amount1) <= IERC20(token1).balanceOf(address(this)));
        }

        slot0.unlocked = true;
    }

    function getCurrentSqrtPriceX96() external view override returns (uint160 sqrtPriceX96){
        sqrtPriceX96 = slot0.sqrtPriceX96;
    }

    function getPositions(int24 tickLower, int24 tickUpper) external view override returns ( uint128 _liquidity, uint256 feeGrowthInside0LastX128,
        uint256 feeGrowthInside1LastX128,
        uint128 tokensOwed0,
        uint128 tokensOwed1){

        Position.Info memory _pos = positions[tickLower][tickUpper];

        _liquidity = _pos.liquidity;
        feeGrowthInside0LastX128 = _pos.feeGrowthInside0LastX128;
        feeGrowthInside1LastX128 = _pos.feeGrowthInside1LastX128;
        tokensOwed0 = _pos.tokensOwed0;
        tokensOwed1 = _pos.tokensOwed1;
    }
}

